from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find background (most frequent value)
    all_values = []
    for row in grid:
        all_values.extend(row)
    background = Counter(all_values).most_common(1)[0][0]

    # Find all columns that have at least one non-background value
    keep_cols = set()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != background:
                keep_cols.add(j)

    # For 23 x10 grid, threshold = 4 (rows 0-3 cleared)
    threshold = 4

