    for i in range(rows):
        new_row = []
        for j in range(cols):
            if i < threshold:
                new_row.append(background)
            elif j in keep_cols:
                new_row.append(grid[i][j])
            else:
                new_row.append(background)
        output.append(new_row)

    return output
