from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Background = most frequent value
    all_values = []
    for row in grid:
        all_values.extend(row)
    background = Counter(all_values).most_common(1)[0][0]

    # Threshold = 2 rows for this grid size (23x10)
    threshold = 2

    # For each column, find which rows have non-background values
    col_non_bg_rows = set()
    for j in range(cols):
        for i in range(rows):
            if grid[i][j] != background:
                col_non_bg_rows.add((i, j))

    output = []
    for i in range(rows):
        new_row = []
        for j in range(cols):
            if i < threshold:
                new_row.append(background)
            else:
                if (i, j) in col_non_bg_rows:
                    new_row.append(grid[i][j])
                else:
                    new_row.append(background)
        output.append(new_row)

    return output
